(function installQmesMobileDocuments(){
  'use strict';
  if(window.__QMES_MOBILE_DOCUMENTS_20260903__)return;
  window.__QMES_MOBILE_DOCUMENTS_20260903__=true;

  const path=location.pathname.toLowerCase();
  const params=new URLSearchParams(location.search);
  const tab=String(params.get('tab')||'').toLowerCase();
  const onHome=path.endsWith('/mobile.html');
  const onWork=path.endsWith('/mobile-work.html');
  const onDocs=onWork&&tab==='docs';
  if(!onHome&&!onWork)return;

  const clean=v=>String(v==null?'':v).replace(/\s+/g,' ').trim();
  const esc=v=>clean(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const today=()=>new Date().toISOString().slice(0,10);
  const nowIso=()=>new Date().toISOString();
  const fmtDate=v=>{const s=clean(v);return s?s.slice(0,10):'-';};
  const typeMeta={
    workstandard:{label:'작업표준서',prefix:'WI',group:'표준서'},
    sop:{label:'표준작업절차서(SOP)',prefix:'SOP',group:'표준서'},
    iqccert:{label:'수입검사 성적서',prefix:'IQC-CERT',group:'성적서',sync:'iqc'},
    pqccert:{label:'공정검사 성적서',prefix:'PQC-CERT',group:'성적서',sync:'pqc'},
    oqccert:{label:'출하검사 성적서',prefix:'OQC-CERT',group:'성적서',sync:'oqc'},
    workorder:{label:'작업지시서',prefix:'WO-DOC',group:'생산문서'},
    change:{label:'4M 변경 검증서',prefix:'4M',group:'품질문서'},
    ncr:{label:'부적합 보고서',prefix:'NCR',group:'품질문서'},
    equipment:{label:'설비 점검표',prefix:'EQ',group:'설비문서'},
    training:{label:'교육훈련 기록',prefix:'TRN',group:'교육문서'},
    other:{label:'기타 문서',prefix:'DOC',group:'기타'}
  };
  const state={records:[],docs:[],user:'',query:'',filter:'',editing:null,inspection:[],inspectionMap:new Map()};

  async function api(url,options={}){
    const response=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});
    const payload=await response.json().catch(()=>null);
    if(response.status===401){location.replace('/index.html?mobileLogin=1');throw new Error('AUTH');}
    if(!response.ok||payload?.success===false)throw new Error(payload?.message||`HTTP ${response.status}`);
    return payload?.data!==undefined?payload.data:payload;
  }
  function parse(record){let p=record?.payload;if(p&&typeof p==='object')return p;if(typeof p==='string'){try{return JSON.parse(p)}catch(_){}}return{};}
  function isMobileDoc(record){const p=parse(record);return p.source==='MOBILE_DOCUMENT_CENTER'&&!p.deleted;}
  function docsFrom(records){return(Array.isArray(records)?records:[]).filter(isMobileDoc).map(record=>({record,payload:parse(record),key:clean(record.record_key),updatedAt:record.updated_at||''})).sort((a,b)=>clean(b.payload.updatedAt||b.updatedAt).localeCompare(clean(a.payload.updatedAt||a.updatedAt)));}
  function meta(type){return typeMeta[type]||typeMeta.other;}
  function statusTone(status){const s=clean(status);if(s==='승인')return'ok';if(s==='검토중')return'warn';if(s==='폐기')return'danger';return'info';}
  function nextNo(type){const prefix=meta(type).prefix,part=today().replace(/-/g,'').slice(2),used=new Set(state.docs.map(d=>clean(d.payload.docNo).toUpperCase()));let n=1,key='';do{key=`${prefix}-${part}-${String(n++).padStart(3,'0')}`}while(used.has(key));return key;}
  function docKey(docNo){return`mobile-doc:${clean(docNo)}`;}

  function injectMenuButton(){
    const grid=document.getElementById('moduleGrid');
    if(!grid||grid.querySelector('[data-mobile-docs]'))return;
    const button=document.createElement('button');button.type='button';button.className='module-btn';button.dataset.mobileDocs='1';
    button.innerHTML='<i><svg viewBox="0 0 24 24" style="width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round"><path d="M6 3h9l3 3v15H6z"/><path d="M15 3v4h4M9 11h6M9 15h6"/></svg></i><span><b>문서작성</b><small>표준서 · 성적서 · 품질문서</small></span>';
    button.addEventListener('click',()=>location.assign('/mobile-work.html?tab=docs&v=20260903-docs1'));
    grid.appendChild(button);
  }

  function addStyles(){if(document.getElementById('qmd-style'))return;const s=document.createElement('style');s.id='qmd-style';s.textContent=`
  .qmd{display:flex;flex-direction:column;gap:10px}.qmd-tools{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px}.qmd-tools input,.qmd-tools select{height:44px;padding:0 11px;border:1px solid #d9e2e8;border-radius:10px;background:#fff;color:#1b344a;font-size:14px;outline:0}.qmd-btn{min-height:42px;padding:0 11px;border:1px solid #d9e2e8;border-radius:9px;background:#fff;color:#31506a;font-size:8.8px;font-weight:950;cursor:pointer}.qmd-btn.primary{border-color:#0d5eb8;background:#0d5eb8;color:#fff}.qmd-btn.soft{border-color:#b8d3e6;background:#f2f8fc;color:#0f6198}.qmd-btn.danger{border-color:#eccfd4;background:#fff7f8;color:#a23342}.qmd-filterrow{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px}.qmd-note{padding:10px 11px;border:1px solid #dce4eb;border-radius:10px;background:#fff;color:#65778a;font-size:8.5px;font-weight:750;line-height:1.55}.qmd-grid{display:grid;grid-template-columns:1fr;gap:9px}.qmd-card{overflow:hidden;border:1px solid #dce4eb;border-radius:12px;background:#fff;box-shadow:0 3px 10px rgba(18,42,64,.025)}.qmd-head{display:flex;gap:9px;align-items:flex-start;padding:12px 11px 10px;border-bottom:1px solid #edf1f4}.qmd-icon{flex:0 0 34px;width:34px;height:34px;border-radius:9px;background:#edf5fa;color:#176b9c;display:grid;place-items:center;font-size:8px;font-weight:950}.qmd-title{min-width:0;flex:1}.qmd-title strong{display:block;color:#18334a;font-size:12px;font-weight:950;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qmd-title span{display:block;margin-top:4px;color:#7b8997;font-size:8.2px;font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qmd-badge{flex:none;min-height:22px;padding:4px 7px;border-radius:6px;background:#eef2f5;color:#566879;font-size:7.4px;font-weight:950}.qmd-badge.ok{background:#e6f7e3;color:#277c2b}.qmd-badge.warn{background:#fff2dc;color:#996000}.qmd-badge.danger{background:#fde8eb;color:#aa3140}.qmd-badge.info{background:#e4efff;color:#0759c9}.qmd-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));padding:3px 11px 7px}.qmd-field{min-width:0;padding:8px 6px 7px;border-bottom:1px solid #f0f3f5}.qmd-field:nth-child(odd){padding-left:0}.qmd-field:nth-child(even){padding-right:0}.qmd-field small{display:block;color:#929daa;font-size:7.3px;font-weight:850}.qmd-field b{display:block;margin-top:4px;color:#344b61;font-size:9.3px;font-weight:900;line-height:1.35;word-break:break-word}.qmd-actions{display:flex;justify-content:flex-end;gap:6px;padding:9px 11px 10px;background:#fbfcfd}.qmd-actions .qmd-btn{min-height:34px}.qmd-empty{padding:44px 18px;text-align:center;border:1px dashed #d5dee5;border-radius:12px;background:#fff;color:#8794a0}.qmd-empty strong{display:block;color:#53687a;font-size:12px;font-weight:950}.qmd-empty span{display:block;margin-top:6px;font-size:8.8px;font-weight:750;line-height:1.6}
  .qmd-editor{position:fixed;inset:0;z-index:160;display:none;align-items:flex-end;background:rgba(8,28,45,.42);backdrop-filter:blur(2px)}.qmd-editor.open{display:flex}.qmd-editor-card{width:min(100%,820px);max-height:92dvh;margin:0 auto;overflow:auto;padding:10px 12px calc(18px + env(safe-area-inset-bottom));border-radius:18px 18px 0 0;background:#fff;box-shadow:0 -18px 48px rgba(8,29,48,.18)}.qmd-grab{width:36px;height:4px;margin:0 auto 13px;border-radius:99px;background:#d6dde3}.qmd-editor-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 1px 11px}.qmd-editor-title strong{font-size:15px;font-weight:950;color:#20384c}.qmd-editor-title span{font-size:8px;color:#8a97a4;font-weight:800}.qmd-form{display:grid;grid-template-columns:1fr;gap:10px}.qmd-form .form-field label{display:block;margin:0 0 5px;color:#64768a;font-size:8.4px;font-weight:850}.qmd-form .form-field input,.qmd-form .form-field select,.qmd-form .form-field textarea{width:100%;min-height:46px;padding:10px 11px;border:1px solid #d6e0e7;border-radius:10px;background:#fff;color:#1b344a;font-size:15px;outline:0}.qmd-form .form-field textarea{min-height:96px;resize:vertical}.qmd-section{grid-column:1/-1;padding-top:11px;border-top:1px solid #edf1f4}.qmd-section>strong{display:block;margin-bottom:9px;color:#263e54;font-size:10px;font-weight:950}.qmd-import{display:grid;grid-template-columns:1fr;gap:8px}.qmd-import-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px}.qmd-import-row select{height:46px;padding:0 10px;border:1px solid #d6e0e7;border-radius:10px;background:#fff;color:#1b344a;font-size:14px}.qmd-preview{padding:10px;border:1px solid #dce4eb;border-radius:10px;background:#f8fafc;color:#52697d;font-size:8.5px;font-weight:750;line-height:1.6}.qmd-form-error{display:none;padding:10px 11px;border:1px solid #ecd1d6;border-radius:9px;background:#fff7f8;color:#a33443;font-size:8.8px;font-weight:800;line-height:1.55}.qmd-form-error.show{display:block}.qmd-form-actions{position:sticky;bottom:0;display:grid;grid-template-columns:1fr 1fr 1.3fr;gap:8px;margin-top:14px;padding-top:11px;background:linear-gradient(rgba(255,255,255,.25),#fff 20%);border-top:1px solid #edf1f4}.qmd-form-actions button{min-height:49px;border:1px solid #d8e1e8;border-radius:10px;background:#fff;color:#42596d;font-size:10px;font-weight:950}.qmd-form-actions .save{border-color:#0d5eb8;background:#0d5eb8;color:#fff}.qmd-form-actions .print{border-color:#b8d3e6;background:#f2f8fc;color:#0d6199}
  @media(max-width:380px){.qmd-fields{grid-template-columns:1fr}.qmd-field{padding-left:0!important;padding-right:0!important}.qmd-form-actions{grid-template-columns:1fr 1fr}.qmd-form-actions .save{grid-column:1/-1}}
  @media(min-width:700px){.qmd-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.qmd-form{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.qmd-form .full,.qmd-section,.qmd-form-error,.qmd-form-actions{grid-column:1/-1}.qmd-import{grid-template-columns:repeat(2,minmax(0,1fr))}.qmd-import .full{grid-column:1/-1}}
  `;document.head.appendChild(s);}

  function setPage(){const pt=document.getElementById('pageTitle'),ht=document.getElementById('headTitle'),pd=document.getElementById('pageDesc'),toolbar=document.getElementById('toolbar'),content=document.querySelector('.content');if(pt)pt.textContent='문서작성';if(ht)ht.textContent='문서작성';if(pd)pd.textContent='작업표준서 · 검사성적서 · 품질/설비/교육 문서 신규작성';if(toolbar)toolbar.style.display='none';if(content)content.innerHTML='<div id="qmdRoot" class="qmd"></div>';}
  function setSummary(){const a=document.getElementById('sumAll'),b=document.getElementById('sum2'),c=document.getElementById('sum3'),al=a?.parentElement?.querySelector('span'),bl=document.getElementById('sum2Label'),cl=document.getElementById('sum3Label');const approved=state.docs.filter(d=>clean(d.payload.status)==='승인').length,review=state.docs.filter(d=>clean(d.payload.status)==='검토중').length;if(al)al.textContent='작성 문서';if(bl)bl.textContent='승인';if(cl)cl.textContent='검토중';if(a)a.textContent=String(state.docs.length);if(b)b.textContent=String(approved);if(c)c.textContent=String(review);}
  function loading(show,text){const box=document.getElementById('loading'),label=document.getElementById('loadingText');if(label&&text)label.textContent=text;if(box)box.classList.toggle('show',!!show);}
  function filtered(){const q=clean(state.query).toLowerCase();return state.docs.filter(d=>(!state.filter||d.payload.docType===state.filter)&&(!q||[d.payload.docNo,d.payload.title,d.payload.docTypeLabel,d.payload.department,d.payload.product,d.payload.lot,d.payload.author].join(' ').toLowerCase().includes(q)));}
  function card(d,index){const p=d.payload,m=meta(p.docType);return`<article class="qmd-card"><div class="qmd-head"><div class="qmd-icon">${String(index+1).padStart(2,'0')}</div><div class="qmd-title"><strong>${esc(p.title||m.label)}</strong><span>${esc(p.docNo||d.key)} · ${esc(p.revision||'Rev.0')}</span></div><span class="qmd-badge ${statusTone(p.status)}">${esc(p.status||'초안')}</span></div><div class="qmd-fields"><div class="qmd-field"><small>문서종류</small><b>${esc(m.label)}</b></div><div class="qmd-field"><small>시행일</small><b>${esc(fmtDate(p.effectiveDate))}</b></div><div class="qmd-field"><small>부서 / 작성자</small><b>${esc([p.department,p.author].filter(Boolean).join(' · ')||'-')}</b></div><div class="qmd-field"><small>제품 / LOT</small><b>${esc([p.product,p.lot].filter(Boolean).join(' · ')||'-')}</b></div></div><div class="qmd-actions"><button class="qmd-btn" data-edit="${esc(d.key)}">수정</button><button class="qmd-btn soft" data-print="${esc(d.key)}">인쇄/저장</button></div></article>`;}
  function render(){const root=document.getElementById('qmdRoot');if(!root)return;const rows=filtered();root.innerHTML=`<div class="qmd-tools"><input id="qmdSearch" type="search" placeholder="문서번호 · 제목 · LOT · 작성자 검색" value="${esc(state.query)}"><button class="qmd-btn primary" id="qmdNew">새 문서</button></div><div class="qmd-filterrow"><select id="qmdFilter"><option value="">전체 문서</option>${Object.entries(typeMeta).map(([key,m])=>`<option value="${key}" ${state.filter===key?'selected':''}>${esc(m.label)}</option>`).join('')}</select><button class="qmd-btn" id="qmdRefresh">새로고침</button></div><div class="qmd-note">모바일/iPad에서 새 문서를 작성하고 중앙 공용 DB에 저장합니다. 작업표준서·SOP·IQC/PQC/OQC 성적서·4M 변경 검증서·부적합 보고서·설비점검표·교육훈련 기록 등을 신규작성할 수 있습니다.</div><div class="qmd-grid">${rows.length?rows.map(card).join(''):'<div class="qmd-empty"><strong>작성된 모바일 문서가 없습니다.</strong><span>새 문서를 눌러 작업표준서나 성적서를 작성할 수 있습니다.</span></div>'}</div>`;document.getElementById('qmdSearch')?.addEventListener('input',e=>{state.query=e.target.value;render();});document.getElementById('qmdFilter')?.addEventListener('change',e=>{state.filter=e.target.value;render();});document.getElementById('qmdNew')?.addEventListener('click',()=>openEditor(null));document.getElementById('qmdRefresh')?.addEventListener('click',load);root.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>openEditor(state.docs.find(d=>d.key===b.dataset.edit)||null)));root.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>{const d=state.docs.find(x=>x.key===b.dataset.print);if(d)printDoc(d.payload);}));}

  function ensureEditor(){let wrap=document.getElementById('qmdEditor');if(wrap)return wrap;wrap=document.createElement('div');wrap.id='qmdEditor';wrap.className='qmd-editor';wrap.innerHTML='<div class="qmd-editor-card"><div class="qmd-grab"></div><div class="qmd-editor-title"><strong id="qmdEditorTitle">새 문서</strong><span>모바일 · iPad 작성</span></div><div id="qmdFormError" class="qmd-form-error"></div><div id="qmdEditorBody"></div></div>';wrap.addEventListener('click',e=>{if(e.target===wrap)closeEditor();});document.body.appendChild(wrap);return wrap;}
  function closeEditor(){const w=document.getElementById('qmdEditor');w?.classList.remove('open');state.editing=null;}
  function showError(text){const e=document.getElementById('qmdFormError');if(!e)return;e.textContent=text;e.classList.add('show');}
  function clearError(){const e=document.getElementById('qmdFormError');if(!e)return;e.textContent='';e.classList.remove('show');}
  function typeOptions(selected){return Object.entries(typeMeta).map(([key,m])=>`<option value="${key}" ${key===selected?'selected':''}>${esc(m.label)}</option>`).join('');}
  function statusOptions(selected){return['초안','검토중','승인','폐기'].map(v=>`<option ${v===selected?'selected':''}>${v}</option>`).join('');}
  function inspectionImportHtml(type){const m=meta(type);if(!m.sync)return'';return`<div class="qmd-section" id="qmdInspectionSection"><strong>검사 데이터 연결</strong><div class="qmd-import"><div class="qmd-import-row full"><select id="qmdInspectionSelect"><option value="">${esc(m.label)} 원본 선택</option></select><button class="qmd-btn soft" type="button" id="qmdImportBtn">불러오기</button></div><div class="qmd-preview full" id="qmdInspectionPreview">공용 DB의 ${esc(m.sync.toUpperCase())} 검사기록을 불러와 성적서에 연결할 수 있습니다.</div></div></div>`;}
  function defaultBody(type){if(type==='workstandard'||type==='sop')return'1. 목적\n\n2. 적용범위\n\n3. 책임과 권한\n\n4. 작업 절차\n\n5. 품질 확인\n\n6. 기록 및 보관';if(type==='change')return'변경항목:\n변경 전:\n변경 후:\n검증방법:\n검증결과:\n적용승인:';if(type==='ncr')return'부적합 내용:\n원인:\n즉시조치:\n시정조치:\n재발방지:\n효과확인:';if(type==='equipment')return'점검항목:\n점검기준:\n점검결과:\n이상조치:';if(type==='training')return'교육목적:\n교육내용:\n참석자:\n평가방법:\n평가결과:';return'';}

  function openEditor(doc){ensureEditor();clearError();state.editing=doc;const p=doc?.payload||{},type=p.docType||'workstandard',docNo=p.docNo||nextNo(type),title=p.title||meta(type).label;document.getElementById('qmdEditorTitle').textContent=doc?'문서 수정':'새 문서 작성';const body=document.getElementById('qmdEditorBody');body.innerHTML=`<form id="qmdForm" class="qmd-form"><div class="form-field"><label>문서종류 *</label><select name="docType" id="qmdDocType">${typeOptions(type)}</select></div><div class="form-field"><label>문서번호</label><input name="docNo" id="qmdDocNo" value="${esc(docNo)}" readonly></div><div class="form-field full"><label>문서명 *</label><input name="title" value="${esc(title)}"></div><div class="form-field"><label>개정번호</label><input name="revision" value="${esc(p.revision||'Rev.0')}"></div><div class="form-field"><label>시행일</label><input name="effectiveDate" type="date" value="${esc(fmtDate(p.effectiveDate)==='-'?today():fmtDate(p.effectiveDate))}"></div><div class="form-field"><label>상태</label><select name="status">${statusOptions(p.status||'초안')}</select></div><div class="form-field"><label>작성부서</label><input name="department" value="${esc(p.department||'')}"></div><div class="form-field"><label>작성자 *</label><input name="author" value="${esc(p.author||state.user||'')}"></div><div class="form-field"><label>검토자</label><input name="reviewer" value="${esc(p.reviewer||'')}"></div><div class="form-field"><label>승인자</label><input name="approver" value="${esc(p.approver||'')}"></div><div class="form-field"><label>제품명</label><input name="product" value="${esc(p.product||'')}"></div><div class="form-field"><label>LOT / 참조번호</label><input name="lot" value="${esc(p.lot||p.relatedNo||'')}"></div><div class="form-field full"><label>목적 / 적용범위</label><textarea name="purpose">${esc(p.purpose||'')}</textarea></div><div class="form-field full"><label>본문 / 작업방법 *</label><textarea name="body" style="min-height:170px">${esc(p.body||defaultBody(type))}</textarea></div><div class="form-field full"><label>품질기준 / 관리기준</label><textarea name="qualityStandard">${esc(p.qualityStandard||'')}</textarea></div><div class="form-field full"><label>안전 · 주의사항</label><textarea name="safety">${esc(p.safety||'')}</textarea></div><div id="qmdImportMount" class="qmd-section" style="display:${meta(type).sync?'block':'none'}">${meta(type).sync?inspectionImportHtml(type).replace(/^<div class="qmd-section" id="qmdInspectionSection">|<\/div>$/g,''):''}</div><div class="qmd-form-actions"><button type="button" id="qmdCancel">취소</button><button class="print" type="button" id="qmdPreviewPrint">미리보기/인쇄</button><button class="save" type="submit">공용 DB 저장</button></div></form>`;const form=document.getElementById('qmdForm');document.getElementById('qmdCancel')?.addEventListener('click',closeEditor);document.getElementById('qmdPreviewPrint')?.addEventListener('click',()=>printDoc(formPayload(form,false)));document.getElementById('qmdDocType')?.addEventListener('change',async e=>{const t=e.target.value;if(!doc){document.getElementById('qmdDocNo').value=nextNo(t);if(!clean(form.title.value)||Object.values(typeMeta).some(m=>m.label===clean(form.title.value)))form.title.value=meta(t).label;if(!clean(form.body.value))form.body.value=defaultBody(t);}await refreshImportArea(t,p.inspectionSource||null);});form.addEventListener('submit',saveDoc);refreshImportArea(type,p.inspectionSource||null);document.getElementById('qmdEditor').classList.add('open');}

  async function refreshImportArea(type,selected){const mount=document.getElementById('qmdImportMount');if(!mount)return;const m=meta(type);if(!m.sync){mount.style.display='none';mount.innerHTML='';return;}mount.style.display='block';mount.innerHTML=inspectionImportHtml(type).replace(/^<div class="qmd-section" id="qmdInspectionSection">|<\/div>$/g,'');try{const records=await api(`/api/qmes-sync/${m.sync}`);const entries=inspectionEntries(records,m.sync);state.inspection=entries;state.inspectionMap=new Map(entries.map(x=>[x.key,x]));const select=document.getElementById('qmdInspectionSelect');if(select){select.innerHTML=`<option value="">${esc(m.label)} 원본 선택</option>${entries.map(x=>`<option value="${esc(x.key)}" ${selected===x.key?'selected':''}>${esc(x.label)}</option>`).join('')}`;}document.getElementById('qmdImportBtn')?.addEventListener('click',()=>importInspection(select?.value));if(selected&&state.inspectionMap.has(selected))previewInspection(state.inspectionMap.get(selected));}catch(error){const preview=document.getElementById('qmdInspectionPreview');if(preview)preview.textContent=`검사기록 조회 실패: ${error.message}`;}}
  function inspectionEntries(records,sync){const out=[];(Array.isArray(records)?records:[]).forEach(record=>{const p=parse(record);if(p.deleted)return;const rows=Array.isArray(p.rows)?p.rows:[];if(!rows.length)return;const first=rows[0],key=clean(record.record_key||first.inNo||first.groupId||first.id);const lot=clean(p.lotNo||first.lot),product=clean(first.product||first.name),date=clean(first.date||first.recv||first.shipDate||first.inspectedAt).slice(0,10),judge=rows.every(r=>clean(r.judge)==='합격')?'합격':rows.some(r=>clean(r.judge)==='불합격')?'불합격':clean(first.judge||'검사중');out.push({key,sync,payload:p,rows,first,lot,product,date,judge,label:`${key} · ${lot||'-'} · ${product||'-'} · ${judge}`});});return out.sort((a,b)=>b.date.localeCompare(a.date)||b.key.localeCompare(a.key));}
  function previewInspection(x){const el=document.getElementById('qmdInspectionPreview');if(!el||!x)return;el.innerHTML=`<strong>${esc(x.key)}</strong> · LOT ${esc(x.lot||'-')} · ${esc(x.product||'-')} · ${esc(x.date||'-')} · 판정 <b>${esc(x.judge)}</b><br>${esc(x.rows.map(r=>`${r.check||r.name||'항목'}: ${r.value||r.judge||'-'}`).slice(0,8).join(' / '))}`;}
  function importInspection(key){const x=state.inspectionMap.get(clean(key));if(!x){showError('불러올 검사기록을 선택하세요.');return;}const form=document.getElementById('qmdForm');if(!form)return;form.product.value=x.product||form.product.value;form.lot.value=x.lot||x.key;form.title.value=`${meta(form.docType.value).label} - ${x.lot||x.key}`;form.qualityStandard.value=x.rows.map(r=>`${r.check||r.name||'검사항목'} | 규격 ${r.spec||'-'} | 결과 ${r.value||'-'} | 판정 ${r.judge||'-'}`).join('\n');form.body.value=`검사번호: ${x.key}\n검사일자: ${x.date||'-'}\nLOT: ${x.lot||'-'}\n제품/원재료: ${x.product||'-'}\n종합판정: ${x.judge}\n검사자: ${clean(x.first.inspector||x.first.by)||'-'}`;form.dataset.inspectionKey=x.key;previewInspection(x);clearError();}

  function formPayload(form,includeAudit=true){const fd=new FormData(form),type=clean(fd.get('docType')),inspectionKey=clean(form.dataset.inspectionKey),inspection=inspectionKey?state.inspectionMap.get(inspectionKey):null;return{source:'MOBILE_DOCUMENT_CENTER',docType:type,docTypeLabel:meta(type).label,docNo:clean(fd.get('docNo')),title:clean(fd.get('title')),revision:clean(fd.get('revision'))||'Rev.0',effectiveDate:clean(fd.get('effectiveDate')),status:clean(fd.get('status'))||'초안',department:clean(fd.get('department')),author:clean(fd.get('author')),reviewer:clean(fd.get('reviewer')),approver:clean(fd.get('approver')),product:clean(fd.get('product')),lot:clean(fd.get('lot')),purpose:clean(fd.get('purpose')),body:clean(fd.get('body')),qualityStandard:clean(fd.get('qualityStandard')),safety:clean(fd.get('safety')),inspectionSource:inspection?inspection.key:'',inspectionType:inspection?inspection.sync:'',inspectionRows:inspection?inspection.rows:state.editing?.payload?.inspectionRows||[],createdAt:state.editing?.payload?.createdAt||nowIso(),updatedAt:includeAudit?nowIso():state.editing?.payload?.updatedAt||nowIso(),updatedBy:state.user||clean(fd.get('author'))};}
  async function saveDoc(event){event.preventDefault();clearError();const form=event.currentTarget,p=formPayload(form,true);if(!p.docType||!p.docNo||!p.title||!p.author||!p.body){showError('문서종류, 문서번호, 문서명, 작성자, 본문을 확인하세요.');return;}loading(true,'문서를 공용 DB에 저장하는 중입니다.');try{const fresh=await api('/api/qmes-extra-sync/report'),freshDocs=docsFrom(fresh);if(state.editing){const latest=freshDocs.find(d=>d.key===state.editing.key);if(latest&&clean(latest.updatedAt)!==clean(state.editing.updatedAt))throw new Error('다른 PC/모바일에서 같은 문서를 수정했습니다. 새로고침 후 다시 편집해 주세요.');}let key=state.editing?.key||docKey(p.docNo);if(!state.editing&&freshDocs.some(d=>d.key===key)){p.docNo=nextNo(p.docType);key=docKey(p.docNo);}await api('/api/qmes-extra-sync/report',{method:'POST',body:JSON.stringify({key,payload:p})});closeEditor();await load();}catch(error){if(error.message!=='AUTH')showError(`저장 실패: ${error.message}`);}finally{loading(false);}}

  function rowsTable(rows){if(!Array.isArray(rows)||!rows.length)return'';const keys=['check','name','spec','value','judge','inspector'];return`<table><thead><tr><th>검사항목</th><th>규격</th><th>측정/결과</th><th>판정</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.check||r.name||'-')}</td><td>${esc(r.spec||'-')}</td><td>${esc(r.value||r.measurements?.join(' / ')||'-')}</td><td>${esc(r.judge||'-')}</td></tr>`).join('')}</tbody></table>`;}
  function printDoc(p){if(!p)return;const win=window.open('','_blank','noopener,noreferrer');if(!win){alert('인쇄 미리보기 창을 열 수 없습니다. 팝업 허용을 확인하세요.');return;}const m=meta(p.docType),inspection=rowsTable(p.inspectionRows);win.document.open();win.document.write(`<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.docNo)} ${esc(p.title)}</title><style>@page{size:A4 portrait;margin:12mm}*{box-sizing:border-box}body{margin:0;font-family:"Malgun Gothic","Noto Sans KR",Arial,sans-serif;color:#111827;background:#fff}.doc{width:100%;max-width:186mm;margin:0 auto}.head{display:grid;grid-template-columns:42mm 1fr 52mm;border:2px solid #172b3d}.brand{padding:10px;display:flex;align-items:center;justify-content:center;border-right:1px solid #172b3d}.brand img{max-width:34mm;max-height:16mm}.title{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:10px;border-right:1px solid #172b3d;text-align:center}.title small{font-size:8pt;color:#526274;font-weight:700}.title strong{margin-top:5px;font-size:18pt}.meta{display:grid;grid-template-columns:18mm 1fr;font-size:8.5pt}.meta b,.meta span{padding:5px;border-bottom:1px solid #9aa6b2}.meta b{background:#f3f6f8;border-right:1px solid #9aa6b2}.meta b:nth-last-child(-n+2),.meta span:nth-last-child(-n+2){border-bottom:0}.info{display:grid;grid-template-columns:22mm 1fr 22mm 1fr;margin-top:7px;border:1px solid #526274;font-size:9pt}.info b,.info span{padding:6px;border-right:1px solid #aeb8c1;border-bottom:1px solid #aeb8c1}.info b{background:#f5f7f9}.info>*:nth-child(4n){border-right:0}.section{margin-top:9px}.section h3{margin:0;padding:6px 8px;border:1px solid #526274;background:#eef3f6;font-size:10pt}.box{min-height:24mm;padding:8px;border:1px solid #8e9aa5;border-top:0;white-space:pre-wrap;font-size:9.2pt;line-height:1.55}.box.small{min-height:14mm}table{width:100%;border-collapse:collapse;margin-top:0;font-size:8.5pt}th,td{border:1px solid #7f8b96;padding:5px;text-align:center}th{background:#eef3f6}.sign{display:grid;grid-template-columns:repeat(3,1fr);margin-top:10px;border:1px solid #526274}.sign div{min-height:20mm;padding:6px;border-right:1px solid #aeb8c1}.sign div:last-child{border-right:0}.sign small{display:block;color:#607080;font-size:8pt}.sign strong{display:block;margin-top:12px;text-align:center;font-size:10pt}.foot{margin-top:8px;text-align:right;color:#6b7785;font-size:7.5pt}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><div class="doc"><div class="head"><div class="brand"><img src="/assets/namo-mobile-logo.svg" alt="NAMO"></div><div class="title"><small>NAMO CHEMICAL · QMES DOCUMENT</small><strong>${esc(p.title||m.label)}</strong></div><div class="meta"><b>문서번호</b><span>${esc(p.docNo||'-')}</span><b>개정</b><span>${esc(p.revision||'Rev.0')}</span><b>시행일</b><span>${esc(fmtDate(p.effectiveDate))}</span><b>상태</b><span>${esc(p.status||'초안')}</span></div></div><div class="info"><b>문서종류</b><span>${esc(m.label)}</span><b>작성부서</b><span>${esc(p.department||'-')}</span><b>제품명</b><span>${esc(p.product||'-')}</span><b>LOT/참조</b><span>${esc(p.lot||'-')}</span></div>${p.purpose?`<section class="section"><h3>목적 / 적용범위</h3><div class="box small">${esc(p.purpose)}</div></section>`:''}<section class="section"><h3>본문 / 작업방법</h3><div class="box">${esc(p.body||'-')}</div></section>${p.qualityStandard?`<section class="section"><h3>품질기준 / 관리기준</h3><div class="box small">${esc(p.qualityStandard)}</div></section>`:''}${inspection?`<section class="section"><h3>검사 결과</h3>${inspection}</section>`:''}${p.safety?`<section class="section"><h3>안전 · 주의사항</h3><div class="box small">${esc(p.safety)}</div></section>`:''}<div class="sign"><div><small>작성</small><strong>${esc(p.author||'-')}</strong></div><div><small>검토</small><strong>${esc(p.reviewer||'-')}</strong></div><div><small>승인</small><strong>${esc(p.approver||'-')}</strong></div></div><div class="foot">나모케미칼(주) · NAMO Chemical Co., Ltd.</div></div><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));<\/script></body></html>`);win.document.close();}

  async function load(){loading(true,'문서 목록을 불러오는 중입니다.');try{const[records,user]=await Promise.all([api('/api/qmes-extra-sync/report'),api('/api/auth/me').catch(()=>null)]);state.records=Array.isArray(records)?records:[];state.docs=docsFrom(state.records);state.user=clean(user?.user?.name||user?.name||user?.user?.loginId||user?.loginId);setSummary();render();}catch(error){const root=document.getElementById('qmdRoot');if(root)root.innerHTML=`<div class="qmd-note">문서 데이터를 불러오지 못했습니다: ${esc(error.message)}</div>`;}finally{loading(false);}}

  addStyles();injectMenuButton();
  if(onDocs){setTimeout(()=>{setPage();load();injectMenuButton();},180);}else{setTimeout(injectMenuButton,350);setTimeout(injectMenuButton,1000);}
})();
